import type { MetadataRoute } from 'next'
import { OG_BG, OG_FG } from '@/lib/og-theme'

export default function manifest(): MetadataRoute.Manifest {
  return {
    name: 'REJ Studio',
    short_name: 'REJ Studio',
    description:
      'Search genes, browse isoforms, and design optimized RNA End-Joining sequences.',
    start_url: '/genes',
    display: 'standalone',
    background_color: OG_BG,
    theme_color: OG_FG,
    // Generated by src/app/icon.tsx (generateImageMetadata). /icon is a
    // public path in the proxy, so these load without a session.
    icons: [
      { src: '/icon/192', sizes: '192x192', type: 'image/png' },
      { src: '/icon/512', sizes: '512x512', type: 'image/png' },
    ],
  }
}
